"""The Alembic migrations match the SQLAlchemy models and can be reversed."""

from alembic import command
from alembic.config import Config
from sqlalchemy import inspect

from src.shared.db import MIGRATIONS_DIR, get_engine


def alembic_config(url):
    config = Config()
    config.set_main_option("script_location", str(MIGRATIONS_DIR))
    config.set_main_option("sqlalchemy.url", url)
    return config


def test_models_and_migrations_have_no_drift(database_url):
    # Raises AutoGenerateDiffsDetected if the models need a new migration.
    command.check(alembic_config(database_url))


def test_migrations_create_expected_tables_and_downgrade_cleanly(database_url):
    tables = set(inspect(get_engine()).get_table_names())
    assert {"tasks", "run_steps", "alembic_version"} <= tables
    command.downgrade(alembic_config(database_url), "base")
    assert set(inspect(get_engine()).get_table_names()) <= {"alembic_version"}
    command.upgrade(alembic_config(database_url), "head")
